{
  "name": "@amykit/plugin-next-steps",
  "version": "0.8.0",
  "description": "A next-steps table as the tracker: a row is a work item, its plan the body, read from the base branch.",
  "type": "module",
  "license": "MIT",
  "author": "Nicolas Melo",
  "homepage": "https://github.com/nicolasmelo1/amy#readme",
  "bugs": "https://github.com/nicolasmelo1/amy/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicolasmelo1/amy.git",
    "directory": "plugins/next-steps"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "amy": {
    "about": "Use it when the list of work is an ordered table of plans kept in a repository instead of a ticket tracker. It mounts a tracker port that only reads: each row is a work item with its plan as the body, and only the top rows count as work at once. The table is read from the base branch, so the order is what was merged, and a workflow on it hands every tracker write to the operator."
  },
  "dependencies": {
    "@amykit/core": "^0.8.0"
  },
  "devDependencies": {
    "@amykit/test-fixtures": "^0.1.0"
  }
}

import type { BaseSource, BaseSourceSnapshot, Comment, Ticket, TrackerReads } from "@amykit/core";
import { Row, placeOf, rowsOf } from "./table.js";

/** The status of a row still in the table. */
export const READY = "ready";
/** The status of a plan that left the table for `docs/design/`. */
export const DELIVERED = "delivered";

export interface NextStepsConfig {
  /** The repository the table lives in, as `owner/name`. */
  repo: string;
  /** The table's path in that repository. */
  table: string;
  /** How many rows from the top are work at once. */
  rows: number;
  /** What a row's branch starts with, before its plan's slug. */
  branchPrefix: string;
}

/**
 * An execution-order table as the tracker: a row is a work item, its plan
 * the body, its place in the table the priority.
 *
 * Everything is read from the base branch, through a snapshot, never from a
 * standing checkout somebody may be editing: the order a person merged is the
 * order, and a half-written row on somebody's disk is not work yet.
 *
 * Reads only. There is no comment thread on a plan and no status to move: a
 * row reaches `delivered` because a person merged the pull request that moved
 * its plan to `docs/design/`, which is the review the order deserves. A
 * workflow mounting this runs with its writes handed to the operator.
 */
export class NextStepsTracker implements TrackerReads {
  constructor(
    private readonly source: BaseSource,
    private readonly config: NextStepsConfig,
  ) {}

  async inProgress(): Promise<Ticket[]> {
    const { rows, snapshots } = await this.read();
    const tickets: Ticket[] = [];
    for (const [index, row] of rows.slice(0, this.config.rows).entries()) {
      tickets.push(await this.ticketOf(row, await snapshots(row.repo), READY, index + 1));
    }
    return tickets;
  }

  async get(ticketId: string): Promise<Ticket | null> {
    const { rows, snapshots } = await this.read();
    const index = rows.findIndex((row) => row.id === ticketId);
    const row = rows[index];
    if (row) return this.ticketOf(row, await snapshots(row.repo), READY, index + 1);

    // Gone from the table: delivered where its design note is, and gone
    // where there is none. The id names the repository, so the answer does
    // not depend on the table still linking it, nor on anything remembered.
    const { repo, slug } = placeOf(ticketId, this.config.repo);
    const snapshot = await snapshots(repo);
    const path = `docs/design/${slug}.md`;
    if ((await snapshot.read(path)) === null) return null;
    return this.ticketOf({ id: ticketId, slug, repo, path, label: slug }, snapshot, DELIVERED);
  }

  /** A plan has no comment thread; the conversation about it is the Conversation port's. */
  async comments(_ticketId: string, _since?: string): Promise<Comment[]> {
    return [];
  }

  async hasReplyAfter(_ticketId: string, _since: string): Promise<boolean> {
    return false;
  }

  /** The table's rows, and one snapshot per repository for the rest of this read. */
  private async read(): Promise<{ rows: Row[]; snapshots: (repo: string) => Promise<BaseSourceSnapshot> }> {
    const taken = new Map<string, Promise<BaseSourceSnapshot>>();
    const snapshots = (repo: string): Promise<BaseSourceSnapshot> => {
      let snapshot = taken.get(repo);
      if (!snapshot) taken.set(repo, (snapshot = this.source.snapshot(repo)));
      return snapshot;
    };
    const table = await (await snapshots(this.config.repo)).read(this.config.table);
    if (table === null) {
      throw new Error(`the next-steps tracker reads ${this.config.table} in ${this.config.repo}, and its base branch has no such file`);
    }
    return { rows: rowsOf(table, { repo: this.config.repo, path: this.config.table }), snapshots };
  }

  private async ticketOf(row: Row, snapshot: BaseSourceSnapshot, status: string, priority?: number): Promise<Ticket> {
    const body = await snapshot.read(row.path);
    if (body === null) {
      throw new Error(`the next-steps table links ${row.path} in ${row.repo} for ${row.id}, and its base branch has no such file`);
    }
    return {
      id: row.id,
      title: titleOf(body) ?? row.label,
      url: `https://github.com/${row.repo}/blob/${snapshot.revision}/${row.path}`,
      branchName: `${this.config.branchPrefix}${row.slug}`,
      status,
      body,
      labels: [],
      repo: row.repo,
      ...(priority === undefined ? {} : { priority }),
    };
  }
}

/** The plan's first `# ` heading, after its declaration. */
function titleOf(body: string): string | undefined {
  const heading = /^# (.+)$/m.exec(withoutDeclaration(body));
  return heading?.[1]?.trim();
}

function withoutDeclaration(body: string): string {
  if (!/^---\r?\n/.test(body)) return body;
  const end = body.indexOf("\n---", 3);
  return end < 0 ? body : body.slice(end + 4);
}

import { BRANCH_SETTINGS, ConfigSchema } from "@amykit/core";

/** What this plugin needs told to it, and nothing more. */
export const configSchema = {
  repo: {
    type: "string",
    required: true,
    description: "the repository the table lives in, as owner/name",
  },
  table: {
    type: "string",
    description: "the table's path in that repository",
    default: "plans/next-steps.md",
  },
  rows: {
    type: "number",
    description: "how many rows from the top are work at once; the rest wait their turn",
    default: 1,
  },
  branchPrefix: {
    type: "string",
    description: "what a row's branch starts with, before its plan's slug",
    default: "plan/",
  },
  ...BRANCH_SETTINGS,
} satisfies ConfigSchema;

export { NextStepsTracker, DELIVERED, READY } from "./NextStepsTracker.js";
export type { NextStepsConfig } from "./NextStepsTracker.js";
export { idOf, placeOf, rowsOf } from "./table.js";
export type { Row } from "./table.js";
export { configSchema } from "./config.js";
export { plugin } from "./plugin.js";

import { definePlugin, GitBaseSource, RepoLayout } from "@amykit/core";
import { NextStepsTracker } from "./NextStepsTracker.js";
import { configSchema } from "./config.js";

export const plugin = definePlugin<typeof configSchema>({
  name: "@amykit/plugin-next-steps",
  configSchema,
  register(registry, ctx) {
    if (!Number.isSafeInteger(ctx.config.rows) || ctx.config.rows < 1) {
      throw new Error(`the next-steps tracker needs rows to be a whole number of one or more, not ${ctx.config.rows}`);
    }
    // The workplace is read when the table is, not while this registers: a
    // tracker mounts before the workflow, and the workspace after it.
    const layout: RepoLayout = {
      get workspaceRoot() { return ctx.checkouts().layout.workspaceRoot; },
      get checkouts() { return ctx.checkouts().layout.checkouts; },
      get defaultBranch() { return ctx.checkouts().layout.defaultBranch; },
      get baseBranch() { return ctx.checkouts().layout.baseBranch; },
    };
    // Reads only. The port is the tracker's, and a workflow mounting it runs
    // with its writes handed to the operator: there is nothing to write to.
    registry.port(
      "tracker",
      new NextStepsTracker(new GitBaseSource(ctx.runner, layout), {
        repo: ctx.config.repo,
        table: ctx.config.table,
        rows: ctx.config.rows,
        branchPrefix: ctx.config.branchPrefix,
      }),
    );
  },
});

/** One row of an execution-order table: the plan it links, and where that plan lives. */
export interface Row {
  /**
   * The work item's id: the plan's slug for a plan in the table's repository,
   * `owner+name+slug` for one in another. Unique across the table, it names
   * the repository even after the row has left it, and it is a file name on
   * every system: the queue and the store keep work under its id, and `+` is
   * in no GitHub owner, repository or slug.
   */
  id: string;
  /** The plan's file name without `.md`. */
  slug: string;
  /** The repository the plan lives in, as `owner/name`. */
  repo: string;
  /** The plan's path in that repository. */
  path: string;
  /** The link's own text, for when the plan carries no heading. */
  label: string;
}

/** `[text](target.md)`, the first one in a row being the row's plan. */
const LINK = /\[([^\]]+)\]\(([^)\s]+\.md)\)/;
/** `owner/name:path/to/plan.md`, a plan in another repository. */
const ELSEWHERE = /^([\w.-]+\/[\w.-]+):(.+)$/;

/**
 * The rows of a markdown table, in the order the table keeps them.
 *
 * A row is a table line whose first link points at a markdown file. A relative
 * link is a plan beside the table, in the table's repository; an
 * `owner/name:` link is a plan in another one, which is how one table orders
 * the work of several. Lines that are not table rows — the prose around the
 * table, a second table further down — are read the same way, so the table is
 * the first run of table lines that link plans, and everything after it ends.
 *
 * A plan linked twice is one row, the first. Two different plans that would
 * be one work item are refused, naming both: discovery cannot tell them apart.
 */
export function rowsOf(text: string, table: { repo: string; path: string }): Row[] {
  const rows: Row[] = [];
  let started = false;
  for (const line of text.split(/\r?\n/)) {
    const row = line.trimStart().startsWith("|") ? rowOf(line, table) : null;
    if (row) {
      started = true;
      const seen = rows.find((each) => each.id === row.id);
      if (!seen) rows.push(row);
      else if (seen.path !== row.path) {
        throw new Error(`the next-steps table links ${seen.path} and ${row.path} in ${row.repo}, and both would be the work item ${row.id}; rename one`);
      }
    } else if (started && !line.trimStart().startsWith("|")) {
      break;
    }
  }
  return rows;
}

function rowOf(line: string, table: { repo: string; path: string }): Row | null {
  const link = LINK.exec(line);
  if (!link) return null;
  const [, label = "", target = ""] = link;
  if (/^[a-z]+:\/\//i.test(target)) return null;
  const elsewhere = ELSEWHERE.exec(target);
  const repo = elsewhere ? elsewhere[1]! : table.repo;
  const path = elsewhere ? clean(elsewhere[2]!) : clean(join(directoryOf(table.path), target));
  const slug = path.slice(path.lastIndexOf("/") + 1, -".md".length);
  return { id: idOf(repo, slug, table.repo), slug, repo, path, label };
}

/** The slug where the plan is the table's own, `owner+name+slug` where it is another repository's. */
export function idOf(repo: string, slug: string, tableRepo: string): string {
  return repo === tableRepo ? slug : `${repo.replace("/", "+")}+${slug}`;
}

/** `owner+name+slug`, the id of a plan in another repository. */
const QUALIFIED = /^([\w.-]+)\+([\w.-]+)\+(.+)$/;

/** A work item's repository and slug, read back from its id. */
export function placeOf(id: string, tableRepo: string): { repo: string; slug: string } {
  const qualified = QUALIFIED.exec(id);
  return qualified ? { repo: `${qualified[1]}/${qualified[2]}`, slug: qualified[3]! } : { repo: tableRepo, slug: id };
}

function directoryOf(path: string): string {
  const at = path.lastIndexOf("/");
  return at < 0 ? "" : path.slice(0, at);
}

function join(directory: string, target: string): string {
  return directory === "" ? target : `${directory}/${target}`;
}

/** `a/./b/../c.md` as `a/c.md`, the path git reads. */
function clean(path: string): string {
  const parts: string[] = [];
  for (const part of path.split("/")) {
    if (part === "" || part === ".") continue;
    if (part === "..") parts.pop();
    else parts.push(part);
  }
  return parts.join("/");
}
